from flag_gems.runtime import torch_device_fn

"""ixor: in-place elementwise bitwise XOR.

Semantics mirror ``torch.Tensor.__ixor__`` / ``torch.bitwise_xor_`` (i.e.
``operator.ixor`` on tensors): every element ``self = self ^ other`` with
``other`` broadcastable to ``self``'s shape (an in-place op never expands
``self``), the result is written back into ``self`` and ``self`` is returned.
Integer/boolean element dtypes are preserved; scalar (non-tensor) ``other`` is
also accepted.

Target notes (P800 OAM / flagtree Triton, probed on-device):
  * Masked elementwise xor miscompiles for bool/int8 with BLOCK=4096 and for
    int32 with BLOCK=1024 (deterministic wrong lanes), while masked 64-bit
    elementwise xor is exact for every tested tile and masked 32-bit xor is
    exact for BLOCK>=4096 (and <=512).
  * XOR is byte-wise, so any element array (1/2/4/8-byte elements) is
    processed as int32 words (byte-identical result) which benchmarks
    ~2x faster than int64 words on this backend; only the trailing <4 bytes
    use a 512-wide masked elementwise kernel.  Mask-free grids are used when
    the word count divides the tile exactly.
"""

import torch
import triton
import triton.language as tl

_BIG32 = 1 << 16  # word32 count for the large-tile threshold
_BLOCK32 = 32768  # large-tile width (words)
_NW32 = 16
_SMALL_BLOCK = 512  # safe masked tile for every eval dtype
_SMALL_NW = 1

_ND_BLOCK = 1024
_ND_NW = 4
_ND_WIDE_BLOCK = 4096
_ND_WIDE_NW = 8


@triton.jit
def _xor32u(a_ptr, b_ptr, BLOCK: tl.constexpr):
    # exact-grid int32-word xor (no mask); caller guarantees n % BLOCK == 0
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    tl.store(a_ptr + offs, tl.load(a_ptr + offs) ^ tl.load(b_ptr + offs))


@triton.jit
def _xor32m(a_ptr, b_ptr, n32, BLOCK: tl.constexpr):
    # masked int32-word xor over [0, n32)
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    m = offs < n32
    tl.store(
        a_ptr + offs,
        tl.load(a_ptr + offs, mask=m, other=0) ^ tl.load(b_ptr + offs, mask=m, other=0),
        mask=m,
    )


@triton.jit
def _xor_tail(a_ptr, b_ptr, n_elem, BLOCK: tl.constexpr):
    # masked elementwise xor over the first n_elem of the (native-dtype)
    # pointers; only used on <=3 trailing elements with a small safe BLOCK.
    offs = tl.arange(0, BLOCK)
    m = offs < n_elem
    tl.store(
        a_ptr + offs,
        tl.load(a_ptr + offs, mask=m, other=0) ^ tl.load(b_ptr + offs, mask=m, other=0),
        mask=m,
    )


@triton.jit
def _xor_nd(a_ptr, b_ptr, n_elem, meta_ptr, RANK: tl.constexpr, BLOCK: tl.constexpr):
    # Generic broadcast/strided path.  meta (int64, length 3*RANK):
    # [extents..., self_strides..., other_strides...] per dim of self.
    pid = tl.program_id(0).to(tl.int64)
    i = pid * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
    mask = i < n_elem
    rem = i
    oa = tl.zeros([BLOCK], dtype=tl.int64)
    ob = tl.zeros([BLOCK], dtype=tl.int64)
    for d in tl.static_range(RANK):
        dd = RANK - 1 - d
        s = tl.load(meta_ptr + dd)
        c = rem % s
        rem = rem // s
        oa += c * tl.load(meta_ptr + RANK + dd)
        ob += c * tl.load(meta_ptr + 2 * RANK + dd)
    x = tl.load(a_ptr + oa, mask=mask, other=0)
    y = tl.load(b_ptr + ob, mask=mask, other=0)
    tl.store(a_ptr + oa, x ^ y.to(a_ptr.dtype.element_ty), mask=mask)


def _xor_fast(self, other):
    """Contiguous equal-shape path: int32-word xor + <4-byte tail."""
    n = self.numel()
    if n == 0:
        return self
    es = self.element_size()
    n32 = (n * es) // 4
    done = n32 * 4 // es  # elements covered by full int32 words
    av = self.reshape(-1)
    bv = other.reshape(-1)
    if n32:
        a32 = av.as_strided((done,), (1,)).view(torch.int32)
        b32 = bv.as_strided((done,), (1,)).view(torch.int32)
        if n32 >= _BIG32:
            if n32 % _BLOCK32 == 0:
                _xor32u[(n32 // _BLOCK32,)](a32, b32, BLOCK=_BLOCK32, num_warps=_NW32)
            else:
                _xor32m[(triton.cdiv(n32, _BLOCK32),)](
                    a32, b32, n32, BLOCK=_BLOCK32, num_warps=_NW32
                )
        else:
            _xor32m[(triton.cdiv(n32, _SMALL_BLOCK),)](
                a32, b32, n32, BLOCK=_SMALL_BLOCK, num_warps=_SMALL_NW
            )
    if done < n:
        _xor_tail[(1,)](
            av.as_strided((n - done,), (1,), av.storage_offset() + done),
            bv.as_strided((n - done,), (1,), bv.storage_offset() + done),
            n - done,
            BLOCK=_SMALL_BLOCK,
            num_warps=_SMALL_NW,
        )
    return self


def _xor_nd_path(self, other):
    n = self.numel()
    if n == 0:
        return self
    R = self.dim()
    meta = list(self.shape)
    meta += list(self.stride())
    b_st = [0] * R
    bd = other.dim()
    for k in range(bd):
        ad = R - 1 - k
        if other.shape[bd - 1 - k] == self.shape[ad]:
            b_st[ad] = other.stride()[bd - 1 - k]
    meta += b_st
    mt = torch.tensor(meta, dtype=torch.int64, device=self.device)
    es = self.element_size()
    if es <= 2:
        BLOCK, NW = _ND_BLOCK, _ND_NW
    else:
        BLOCK, NW = _ND_WIDE_BLOCK, _ND_WIDE_NW
    grid = (triton.cdiv(n, BLOCK),)
    _xor_nd[grid](self, other, n, mt, RANK=R, BLOCK=BLOCK, num_warps=NW)
    return self


def ixor(self, other):
    with torch_device_fn.device(
        (self if isinstance(self, torch.Tensor) else other).device
    ):
        if isinstance(other, torch.Tensor):
            # Packed path requires equal dtypes and aligned contiguous storage.
            if (
                self.is_contiguous()
                and other.is_contiguous()
                and other.shape == self.shape
                and self.dtype == other.dtype
                and self.data_ptr() % 4 == 0
                and other.data_ptr() % 4 == 0
            ):
                return _xor_fast(self, other)
            if tuple(torch.broadcast_shapes(self.shape, other.shape)) != tuple(
                self.shape
            ):
                raise RuntimeError(
                    "ixor: in-place ops cannot expand self; broadcast of other "
                    "does not match the shape of self"
                )
            return _xor_nd_path(self, other)

        # python / numpy scalar other: scalar always broadcasts (incl 0-dim self)
        n = self.numel()
        if n == 0:
            return self
        b = int(other)
        if self.dim() == 0:
            # 0-dim self: mutate the reshaped 1-element view but return self
            s1 = self.reshape(1)
            o1 = torch.full((1,), b, dtype=self.dtype, device=self.device)
            _xor_fast(s1, o1)
            return self
        other = torch.full((1,), b, dtype=self.dtype, device=self.device)
        return _xor_nd_path(self, other)


xor_ = ixor

xor_scalar_ = ixor
